    ["We have accepted the declaration of war from <Highlight_L>[%s]</>. The war starts at <Highlight_L>[Today %s]</>!"] = "Мы приняли объявление войны от <Highlight_L>[%s]</>. Война начинается в <Highlight_L>[Today %s]</>!",
    ["Wing Blade Horizontal Slash"] = "Горизонтальный разрез лопасти крыла",
